let sequence = 0;
const setup = () => {
    const project = path.join(root, String(sequence++));
    for (const [file, content] of Object.entries(generated)) {
        const filePath = path.join(project, 'src', file);
        fs.mkdirSync(path.dirname(filePath), { recursive: true });
        fs.writeFileSync(filePath, content);
    }
    const rootFolder = path.join(project, 'src');
    const sales = path.join(rootFolder, 'bounded-contexts/sales');
    const billing = path.join(rootFolder, 'bounded-contexts/billing');
    const sharedKernel = path.join(rootFolder, 'shared-kernel');
    const unit = (kind: BackendUnit['kind'], name: string) =>
        findBackendUnits(sales).find(
            (x) => x.kind === kind && x.name === name
        ) as BackendUnit;
    const read = (file: string) =>
        fs.readFileSync(path.join(rootFolder, file), 'utf8');
    const exists = (file: string) => fs.existsSync(path.join(rootFolder, file));
    const move = (u: BackendUnit, target: Partial<BackendUnit>) => {
        const result = moveBackendUnit(project, rootFolder, u, {
            ownerPath: u.ownerPath,
            name: u.name,
            aggregate: u.aggregate,
            ...target
        });
        writePendingChanges();
        return result;
    };
    return {
        rootFolder,
        sales,
        billing,
        sharedKernel,
        unit,
        read,
        exists,
        move
    };
};

test('finds units by their file layout, with implementation labels', () => {
    const { sales, unit } = setup();
    expect(
        findBackendUnits(sales).map((x) =>
            [x.kind, x.name, x.aggregate ?? '', x.labels.join(',')].join(' ')
        )
    ).toEqual([
        'aggregate order  in-memory,prisma',
        'entity order-line order ',
        'value-object money  ',
        'domain-service pricing  ',
        'port payment-gateway  api,mock',
        'query order-summary  in-memory,prisma',
        'use-case place-order  '
    ]);
    expect(unit('aggregate', 'order').ownerPath).toBe(sales);
});

test('renaming an aggregate renames its files, classes, wires, dependents and in-memory section', () => {
    const { unit, read, exists, move } = setup();
    const result = move(unit('aggregate', 'order'), { name: 'purchase' });
    expect(result.violations).toBeUndefined();
    const sales = 'bounded-contexts/sales';
    expect(exists(`${sales}/domain/aggregates/order`)).toBe(false);
    expect(
        read(`${sales}/domain/aggregates/purchase/purchase.aggregate-root.ts`)
    ).toContain('export class Purchase extends domainType()');
    expect(
        read(
            `${sales}/domain/aggregates/purchase/purchase.aggregate-root.spec.ts`
        )
    ).toContain('let purchase: Purchase\n');
    expect(
        read(
            `${sales}/domain/aggregates/purchase/purchase.aggregate-root.spec.ts`
        )
    ).toContain("describe('purchase'");
    // Entities inside move along and keep their names
    expect(
        read(
            `${sales}/domain/aggregates/purchase/entities/order-line.entity.ts`
        )
    ).toContain('export class OrderLine');
    expect(
        read(
            `${sales}/infrastructure/repositories/prisma/prisma-purchase-repository.ts`
        )
    ).toContain(
        'export class PrismaPurchaseRepository implements PurchaseRepository'
    );
    const inMemory = read(
        `${sales}/infrastructure/repositories/in-memory/in-memory-purchase-repository.ts`
    );
    expect(inMemory).toContain("InMemoryDbInfrastructureService['purchases']");
    expect(inMemory).toContain('inMemoryDbInfrastructureService.purchases');
    expect(
        read(`${sales}/wiring/repositories/wire-purchase-repository.ts`)
    ).toContain('export const wirePurchaseRepository = envBranchedWire');
    const useCase = read(
        `${sales}/application/use-cases/place-order-use-case.ts`
    );
    expect(useCase).toContain(
        "import type { PurchaseRepository } from '../../domain/aggregates/purchase/purchase-repository'"
    );
    expect(useCase).toContain(
        'private readonly purchaseRepository: PurchaseRepository,'
    );
    // Other names containing the old one stay
    expect(useCase).toContain('export class PlaceOrderUseCase');
    expect(
        read(`${sales}/wiring/use-cases/wire-place-order-use-case.ts`)
    ).toContain('[wirePurchaseRepository, ');
    const db = read(
        'shared-kernel/infrastructure/services/in-memory-db-infrastructure-service.ts'
    );
    expect(db).toContain(
        "import type { Purchase } from '../../../bounded-contexts/sales/domain/aggregates/purchase';"
    );
    expect(db).toContain("purchases = this.section<Purchase>('PURCHASES');");
    expect(
        read(`${sales}/domain/services/pricing-domain-service.ts`)
    ).toContain("import { Purchase, OrderLine } from '../aggregates/purchase'");
});

test("renaming a port renames its adapters, wire and the dependents' parameters", () => {
    const { unit, read, move } = setup();
    move(unit('port', 'payment-gateway'), { name: 'payment-provider' });
    const sales = 'bounded-contexts/sales';
    expect(read(`${sales}/application/ports/payment-provider.ts`)).toContain(
        'export abstract class PaymentProvider'
    );
    expect(
        read(
            `${sales}/infrastructure/application-adapters/api/api-payment-provider.ts`
        )
    ).toContain('export class ApiPaymentProvider extends PaymentProvider');
    expect(
        read(
            `${sales}/infrastructure/application-adapters/mock/mock-payment-provider.ts`
        )
    ).toContain('export class MockPaymentProvider extends PaymentProvider');
    expect(
        read(`${sales}/wiring/application-ports/wire-payment-provider.ts`)
    ).toContain('export const wirePaymentProvider = envBranchedWire');
    expect(
        read(`${sales}/application/use-cases/place-order-use-case.ts`)
    ).toContain('private readonly paymentProvider: PaymentProvider,');
});

test('a move that would make a context import another one is refused and stages nothing', () => {
    const { unit, billing, exists, move } = setup();
    const result = move(unit('query', 'order-summary'), { ownerPath: billing });
    expect(result.violations).toContainEqual([
        expect.stringMatching(
            /sales\/application\/use-cases\/place-order-use-case\.ts$/
        ),
        expect.stringMatching(
            /billing\/application\/queries\/order-summary-query$/
        )
    ]);
    expect(
        exists(
            'bounded-contexts/sales/application/queries/order-summary-query.ts'
        )
    ).toBe(true);
    expect(exists('bounded-contexts/billing/application')).toBe(false);
});

test('a value object moves to the Shared Kernel and its importers follow', () => {
    const { unit, sharedKernel, read, exists, move } = setup();
    const result = move(unit('value-object', 'money'), {
        ownerPath: sharedKernel
    });
    expect(result.violations).toBeUndefined();
    expect(
        exists(
            'bounded-contexts/sales/domain/value-objects/money.value-object.ts'
        )
    ).toBe(false);
    expect(
        read('shared-kernel/domain/value-objects/money.value-object.ts')
    ).toContain('export class Money');
});

test('an entity leaving its aggregate is no longer re-exported there and its importers import it directly', () => {
    const { unit, read, exists, move } = setup();
    move(unit('entity', 'order-line'), { aggregate: undefined });
    const sales = 'bounded-contexts/sales';
    expect(exists(`${sales}/domain/entities/order-line.entity.ts`)).toBe(true);
    expect(read(`${sales}/domain/aggregates/order/index.ts`)).not.toContain(
        'order-line'
    );
    expect(
        read(`${sales}/domain/services/pricing-domain-service.ts`)
    ).toContain(
        "import { Order } from '../aggregates/order'\nimport { OrderLine } from '../entities/order-line.entity'"
    );
});

test('a value object joining an aggregate is re-exported by it', () => {
    const { unit, read, move } = setup();
    move(unit('value-object', 'money'), { aggregate: 'order' });
    expect(
        read('bounded-contexts/sales/domain/aggregates/order/index.ts')
    ).toContain("export * from './value-objects/money.value-object'");
});

test('validation: kebab names, Shared Kernel kinds, existing targets and no-op moves', () => {
    const { unit, sharedKernel, billing } = setup();
    const query = unit('query', 'order-summary');
    expect(
        validateBackendMove(
            query,
            { ownerPath: query.ownerPath, name: 'OrderSummary' },
            sharedKernel
        )
    ).toMatch(/kebab-case/);
    expect(
        validateBackendMove(
            query,
            { ownerPath: sharedKernel, name: 'order-summary' },
            sharedKernel
        )
    ).toBe('Queries are not part of the Shared Kernel');
    expect(
        validateBackendMove(
            query,
            { ownerPath: query.ownerPath, name: 'order-summary' },
            sharedKernel
        )
    ).toMatch(/Nothing to change/);
    const money = unit('value-object', 'money');
    expect(
        validateBackendMove(
            money,
            { ownerPath: billing, name: 'invoice-number' },
            sharedKernel
        )
    ).toMatch(/invoice-number\.value-object\.ts already exists/);
    expect(filesToOverwrite()).toEqual([]);
});
